#!/usr/bin/env bash
# Install and enroll a Wazuh agent on Ubuntu (amd64).
#
# Origin: [Documented] the wget + dpkg command with WAZUH_MANAGER / WAZUH_AGENT_GROUP /
#         WAZUH_AGENT_NAME variables is the one generated by the Wazuh dashboard
#         ("Deploy new agent") in the project. Wrapping it in a script, the variables
#         and the service enable/start steps are [Recommendation].
#
# Usage:
#   WAZUH_MANAGER=<manager address, e.g. its Tailscale IP> \
#   WAZUH_AGENT_NAME=WEB-SERVER ./install-agent-ubuntu.sh
set -euo pipefail

: "${WAZUH_MANAGER:?Set WAZUH_MANAGER to the Wazuh manager address}"
AGENT_NAME="${WAZUH_AGENT_NAME:-$(hostname)}"
AGENT_GROUP="${WAZUH_AGENT_GROUP:-default}"
AGENT_VERSION="${WAZUH_AGENT_VERSION:-4.7.5}"     # version used in the project; use one compatible with your manager
DEB="wazuh-agent_${AGENT_VERSION}-1_amd64.deb"

cd "$(mktemp -d)"
wget "https://packages.wazuh.com/4.x/apt/pool/main/w/wazuh-agent/${DEB}"
sudo WAZUH_MANAGER="${WAZUH_MANAGER}" \
     WAZUH_AGENT_GROUP="${AGENT_GROUP}" \
     WAZUH_AGENT_NAME="${AGENT_NAME}" \
     dpkg -i "./${DEB}"

sudo systemctl daemon-reload
sudo systemctl enable wazuh-agent
sudo systemctl start wazuh-agent
echo "Agent '${AGENT_NAME}' installed. Check it in the dashboard (Agents) and with: scripts/linux/verify-agent.sh"
